"""
Generates dlib/tokenizer/hf_unicode.h, the Unicode character classes used by the
pre-tokenizers of hf_tokenizer, from the unicodedata module of Python.

    python3 make_unicode_table.py > ../../../tokenizer/hf_unicode.h
"""

import sys
import unicodedata

CLASSES = {
    "Lu": 1, "Ll": 2, "Lt": 3, "Lm": 4, "Lo": 5,
    "Mn": 6, "Mc": 6, "Me": 6,
    "Nd": 7, "Nl": 7, "No": 7,
    "Pc": 8, "Pd": 8, "Ps": 8, "Pe": 8, "Pi": 8, "Pf": 8, "Po": 8,
    "Sm": 9, "Sc": 9, "Sk": 9, "So": 9,
    "Zs": 10, "Zl": 10, "Zp": 10,
}

# The White_Space property of the Unicode Character Database.
WHITE_SPACE = [0x09, 0x0A, 0x0B, 0x0C, 0x0D, 0x20, 0x85, 0xA0, 0x1680] + list(range(0x2000, 0x200B)) \
    + [0x2028, 0x2029, 0x202F, 0x205F, 0x3000]


def main():
    entries = []
    prev = None
    for cp in range(0x110000):
        c = CLASSES.get(unicodedata.category(chr(cp)), 0)
        if c != prev:
            entries.append((cp << 4) | c)
            prev = c
    out = sys.stdout
    out.write("""// Copyright (C) 2026 Cydral Technology (cydraltechnology@gmail.com)
// License: Boost Software License   See LICENSE.txt for the full license.
#ifndef DLIB_HF_UNICODE_H_
#define DLIB_HF_UNICODE_H_

// Generated by make_unicode_table.py from the Unicode Character Database %s.

#include <algorithm>
#include <cstdint>

namespace dlib
{
    namespace hf_unicode
    {
        /*!
            The character classes the pre-tokenizers of the byte-level BPE vocabularies
            are written with: the letters by case (\\p{Lu}, \\p{Ll}, \\p{Lt}, \\p{Lm},
            \\p{Lo}), the marks (\\p{M}), the numbers (\\p{N}), the punctuation (\\p{P}),
            the symbols (\\p{S}) and the separators (\\p{Z}); "other" gathers the control,
            format, private use and unassigned code points.
        !*/
        enum char_class : uint8_t { other = 0, Lu, Ll, Lt, Lm, Lo, M, N, P, S, Z };

        // Code point at which each run of one class starts, shifted left by 4, with
        // the class in the low 4 bits; the runs cover [0, 0x110000).
        inline const uint32_t* class_runs(size_t& count)
        {
            static const uint32_t runs[] = {
""" % unicodedata.unidata_version)
    line = "               "
    for i, e in enumerate(entries):
        item = " 0x%x," % e
        if len(line) + len(item) > 100:
            out.write(line + "\n")
            line = "               "
        line += item
    out.write(line + "\n")
    out.write("""            };
            count = sizeof(runs) / sizeof(runs[0]);
            return runs;
        }

        inline char_class classify(uint32_t cp)
        {
            if (cp >= 0x110000) return other;
            size_t count = 0;
            const uint32_t* runs = class_runs(count);
            // Last run starting at or before cp.
            const uint32_t key = (cp << 4) | 0xF;
            const uint32_t* it = std::upper_bound(runs, runs + count, key);
            return static_cast<char_class>(*(it - 1) & 0xF);
        }

        inline bool is_white_space(uint32_t cp)
        {
            if (cp < 0x80) return (cp >= 0x09 && cp <= 0x0D) || cp == 0x20;
            switch (cp)
            {
""")
    for cp in WHITE_SPACE:
        if cp >= 0x80:
            out.write("            case 0x%X:\n" % cp)
    out.write("""                return true;
            default:
                return false;
            }
        }

        // The canonical combining class: (first code point of a run << 8 | class).
        inline const uint32_t* combining_runs(size_t& count)
        {
            static const uint32_t runs[] = {
""")
    runs = []
    prev = None
    for cp in range(0x110000):
        c = unicodedata.combining(chr(cp))
        if c != prev:
            runs.append((cp << 8) | c)
            prev = c
    line = "               "
    for e in runs:
        item = " 0x%x," % e
        if len(line) + len(item) > 100:
            out.write(line + "\n")
            line = "               "
        line += item
    out.write(line + "\n")
    out.write("""            };
            count = sizeof(runs) / sizeof(runs[0]);
            return runs;
        }

        inline unsigned combining_class(uint32_t cp)
        {
            if (cp < 0x300 || cp >= 0x110000) return 0;
            size_t count = 0;
            const uint32_t* runs = combining_runs(count);
            const uint32_t* it = std::upper_bound(runs, runs + count, (cp << 8) | 0xFF);
            return *(it - 1) & 0xFF;
        }

        // The primary composites of the canonical composition: (first << 21 | second)
        // in increasing order, and the composite of each pair.
        inline const uint64_t* composition_keys(size_t& count, const uint32_t*& composites)
        {
            static const uint64_t keys[] = {
""")
    pairs = []
    for cp in range(0x110000):
        d = unicodedata.decomposition(chr(cp))
        if not d or d.startswith("<"):
            continue
        parts = [int(x, 16) for x in d.split()]
        if len(parts) != 2:
            continue
        a, b = parts
        if unicodedata.normalize("NFC", chr(a) + chr(b)) == chr(cp):
            pairs.append(((a << 21) | b, cp))
    pairs.sort()
    line = "               "
    for k, _ in pairs:
        item = " 0x%xull," % k
        if len(line) + len(item) > 100:
            out.write(line + "\n")
            line = "               "
        line += item
    out.write(line + "\n")
    out.write("""            };
            static const uint32_t values[] = {
""")
    line = "               "
    for _, c in pairs:
        item = " 0x%x," % c
        if len(line) + len(item) > 100:
            out.write(line + "\n")
            line = "               "
        line += item
    out.write(line + "\n")
    out.write("""            };
            count = sizeof(keys) / sizeof(keys[0]);
            composites = values;
            return keys;
        }

        // The canonical composite of a followed by b, or 0 when they do not compose.
        inline uint32_t compose(uint32_t a, uint32_t b)
        {
            // Hangul syllables, composed algorithmically.
            if (a >= 0x1100 && a < 0x1113 && b >= 0x1161 && b < 0x1176)
                return 0xAC00 + ((a - 0x1100) * 21 + (b - 0x1161)) * 28;
            if (a >= 0xAC00 && a < 0xD7A4 && (a - 0xAC00) % 28 == 0 && b > 0x11A7 && b < 0x11C3)
                return a + (b - 0x11A7);
            size_t count = 0;
            const uint32_t* composites = nullptr;
            const uint64_t* keys = composition_keys(count, composites);
            const uint64_t key = (static_cast<uint64_t>(a) << 21) | b;
            const uint64_t* it = std::lower_bound(keys, keys + count, key);
            return (it != keys + count && *it == key) ? composites[it - keys] : 0;
        }
    }
}

#endif // DLIB_HF_UNICODE_H_
""")


if __name__ == "__main__":
    main()
